                    nr, nc = cr + dr, cc + dc
                    if (0 <= nr < height and 0 <= nc < width
                            and (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        cells.add((nr, nc))
                        queue.append((nr, nc))
            result.append((color, cells))
    return result


def _longest_straight_run(cells):
    rows, columns = defaultdict(set), defaultdict(set)
    for r, c in cells:
        rows[r].add(c)
        columns[c].add(r)
    best = 0
    for lines in (rows, columns):
        for values in lines.values():
            run = 0
            previous = None
            for value in sorted(values):
                run = run + 1 if previous is not None and value == previous + 1 else 1
                best = max(best, run)
                previous = value
    return best


def _shape(cells):
    """Translation-normalized shape; orientation is significant."""
    top = min(r for r, _ in cells)
    left = min(c for _, c in cells)
    return frozenset((r - top, c - left) for r, c in cells)


def _center(cells):
    return (sum(r for r, _ in cells) / len(cells),
            sum(c for _, c in cells) / len(cells))


def transform(grid):
    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    components = _components(grid, background)

    # The distinctive guide object reaches an edge and has the longest straight
    # arm (the demos use this object to supply the replacement color).
    edge_components = [
        (color, cells) for color, cells in components
        if any(r in (0, height - 1) or c in (0, width - 1) for r, c in cells)
    ]
    if not edge_components:
